          body: '<p><b>主题不变（AI 为什么不提你），但换了个写法</b>——不再是「对比一下就懂了」，而是<b>把中间那层机制讲出来</b>，再落到一句同行会收藏的话：<b>「形容词好写，是因为它不用负责」</b>。</p><p style="margin:10px 0 6px;font-size:12.5px;color:#0a3d62;"><b>✏️ v1 → v2 改了什么（2026-09-11 按用户反馈）</b></p><div class="ct-body ph"><b>① 去 AI 味</b>：不再「每段 1–2 句 + 强行空行」。那种极短的、长度均匀的段落本身就是 AI 排版的特征，v2 改成<b>长短交错</b>，有的段 4 行，有的段就一句；破折号从 3 个减到 1 个；加了口语碎词（「不太服气」「我问为啥」「说白了」）。<br/><b>② 补深度</b>：加了「AI 是把能单独拎出来的句子抽出来拼成回答」这一层机制，解释了<b>为什么</b>形容词摘不走（抄过去用户还是不知道买哪个型号），而不是只给结论。<br/><b>③ 加反转</b>：v1 是「他改了就好了」，太顺。v2 是<b>他改了又改回去</b>——因为老板觉得具体像说明书。真实做官网的人都懂这一步。<br/><b>④ 加洞察</b>：把「为什么官网全是套话」归因到<b>责任成本</b>——写具体就要为结果背锅，写漂亮话谁也挑不出毛病。<br/><b>⑤ 保留认可的部分</b>：对照 / 机制 / 落地 / 只改一处 / 不敢下结论这条主线不动。</div><p class="ct-h">📌 标题 3 选 1（替换时一并改标题）</p><div class="ct-body ph"><b>主推：</b>为什么官网全是套话，我说实话：因为不敢写<br/><b>备选 A：</b>「品质卓越」这句话为什么 AI 抄不走<br/><b>备选 B：</b>我劝了半天，他还是把那句改回去了<br/><span style="color:#8a8a85;">主推把最有洞察的那一句顶在标题上，同行会点进来；备选 B 最有故事感、最不像营销号。都避开极限词。</span></div><p class="ct-h">🖼 封面建议 · 3:4 竖图 1080×1440（模板 A · 真实场景照）</p><div class="ct-body ph"><b>尺寸固定：竖图 3:4，1080×1440px。</b><br/>拍一张<b>你手机或电脑上 AI 回答的界面</b>——就拍那句「提到了三家同行、没提你」，不用打码，越像随手截的越好。<br/>主文案压在画面<b>中上部</b>（纵向 1/4 到 1/2 处）：<br/>「<b>品质卓越<br/>AI 抄不走</b>」<br/>⚠️ <b>底部 15%（约 216px）必须留空</b>——会被笔记标题和点赞栏压住。<br/><b>备选（模板 C · 聊天截图）</b>：朋友那句「我们在 AI 里搜不到」的聊天记录，打码只打头像，正文留着。</div><p class="ct-h">👥 这篇在跟谁说话</p><div class="ct-body ph">① <b>制造业 / B2B 老板</b>：官网常年挂着「品质卓越」，一看一个准，而且能看懂自己在躲什么；<br/>② <b>市场 / SEO 同行</b>：「形容词不用负责」这句他们会直接拿去复述给客户听；<br/>③ <b>做官网改版的乙方</b>：拍板难才是真痛点，代入感极强。</div>'
