          body: '<p><b>本篇是已发笔记的「故事化重写版」（v3）</b>：同样讲 GEO 团体标准，但不再当资讯盘点写，改成<b>一个半夜刷到截图、先松口气又突然有点慌的小故事</b>。钩子在开头（「划到那条没划走」），情绪转折在中间（松口气→咯噔一下），不讲课、不解释机制，让「标准=护城河也=降价通知书」从故事里自己长出来。</p><p style="margin:10px 0 6px;font-size:12.5px;color:#0a3d62;"><b>📰 故事里用到的真实背景（2026-09-10 已核实）</b></p><div class="ct-body ph">《生成式引擎优化(GEO)可信信息传播与信息生态治理规范》(T/CAPT 026—2026)：2026-08 发布，新华网、新华社国家重点实验室牵头，30 余家机构参与；明确禁止语料投毒、答案霸权、伪共识制造、提示词注入攻击四类违规。<br/><span style="color:#8a8a85;">⚠️ 口径：只写量级与趋势，不给精确数字；机构全称、日期宁可模糊绝不补。</span></div><p class="ct-h">📌 标题 3 选 1（钩子优先）</p><div class="ct-body ph"><b>主推：</b>半夜刷到一张截图，我突然有点慌<br/><b>备选 A：</b>同行群里那张图，把我从床上惊起来<br/><b>备选 B：</b>终于有规矩了，但我担心的正是这个<br/><span style="color:#8a8a85;">主推把「半夜刷到→有点慌」的悬念顶在标题，点击动机最明确；备选 B 点出矛盾，适合封面大字。</span></div><p class="ct-h">🖼 封面建议 · 3:4 竖图 1080×1440（模板 C · 真实群聊截图）</p><div class="ct-body ph"><b>尺寸固定：竖图 3:4，1080×1440px。</b><br/>直接拍<b>同行群里那条甩链接的消息</b>——屏幕上露出发言头像和那个链接，越像随手截的越好。<br/>主文案压在画面<b>中上部</b>：<br/>「<b>半夜刷到<br/>有点慌</b>」<br/>⚠️ <b>底部 15%（约 216px）必须留空</b>。</div><p class="ct-h">👥 这篇在跟谁说话</p><div class="ct-body ph">① <b>GEO / SEO 同行</b>：「被比价」是真实焦虑，会转述；② <b>甲方市场负责人</b>：第一次知道有标准可参考；③ <b>观望的人</b>：得到「这行不是一波流」的判断依据。</div>'
