          body: '<div style="background:#fff8f0;border:1px solid #ffcfa8;border-radius:12px;padding:12px 14px;"><b style="font-size:13.5px;color:#b8541a;">📈 今日涨粉动作（30 分钟内做完）</b><div style="font-size:12.5px;line-height:1.8;color:#2c2c2c;margin-top:8px;"><p style="margin:0 0 6px;"><b>1. 发布时段：07:00–09:30 随机落点。</b>建议 <b>08:10</b> 前后——Day 15 是 08:25，错开别卡同一个点。</p><p style="margin:0 0 6px;"><b>2. 发完 30 分钟内回到评论区</b>：置顶带核心词那条，再回前 5 条真实评论。</p><p style="margin:0 0 6px;"><b>3. 和 Day 15 挂进同一个合集</b>：合集名「<b>AI 搜不到你？正反两个案例</b>」——合集名带核心词，本身就是一个搜索入口。</p><p style="margin:0 0 6px;"><b>4. 自己去搜索框验一次</b>：发完 2 小时后搜「AI 搜不到」「为什么 AI 不提我的公司」，看下拉词里有没有这篇，没有就说明词还没被识别，再等等或微调标题。</p><p style="margin:0 0 6px;"><b>5. 24 小时后复盘 4 个数：</b>曝光、评论、收藏 + <b>搜索来源占比</b>。这篇重点看<b>搜索占比</b>——它是验证"补搜索词有没有用"的第一篇对照数据。</p><p style="margin:6px 0 0;font-size:11.5px;color:#8a8a85;"><b>小提醒</b>：行业和姓氏都是化名口径，别写人家真名；"层高不到 4 米"这种结论要改成你自己行业里说得通的那句。</p></div></div>'
