          body: '<p class="ct-h">🏷️ 话题标签（10 个，直接复制）</p><div class="ct-body ph" style="word-break:break-all;">#品牌在AI里的存在感 #被AI收录 #AI搜不到我们公司 #豆包 #DeepSeek #元宝 #GEO #中小企业 #品牌营销 #AI工具</div><div style="font-size:11.5px;color:#8a8a85;margin-top:4px;">标签结构：<b>3 个搜索词 + 3 个平台词 + 2 个赛道词 + 2 个流量词</b>。平台词用 豆包 / DeepSeek / 元宝，与 Day 18（豆包 / 百度AI搜索 / Kimi）只重合 1 个。<br/>「品牌在 AI 里的存在感」是老板视角词，搜索意图比"被 AI 收录"更贴近决策者，这篇值得多等几天看长尾。</div><p class="ct-h">💬 互动钩子 · D 类「求故事（软化的邀请式）」</p><div class="ct-body ph"><b>⓪ 结尾三段式（收束 + 软化 + 邀请）</b>：① 收束——"这事我到现在也没完全想透，品牌在 AI 里的存在感到底是看量还是看质"；② 软化——"你们要是也好奇自己在 AI 嘴里是什么形象"；③ 邀请——"评论区跟我讲讲你被说成了谁，我还挺想听"。⚠️ <b>动词用「讲讲、说说」，别用「报下、撂、扣 1」。</b><br/><b>① 为什么用 D 类</b>：Day 18 A、Day 17 E、Day 16 D、Day 15 B、Day 14 C，D 类隔了 Day 17/18 两篇，安全。<br/><b>② 别问"你们行业是什么"</b>：问"被 AI 说成了谁"门槛更低，答的人会顺手把行业带出来，比直接要行业自然。<br/><b>③ 预埋 3 条评论</b>（发文后 10 分钟内，第 1 条置顶带核心词）：<br/>　·「补一句：存在感不是被提到就算，要看 AI 嘴里的那句能不能带来客户」<br/>　·「我自检完也懵了，AI 把我们一个客户说成了竞品」<br/>　·「四问里最扎心的是第 4 问，它压根没给官网」<br/><b>④ 有人问"那到底先改哪"</b>：老实说一句"先让 AI 提对，再让它带上官网"，别把话说死。</div>'
