          body: '<div style="background:#fff8f0;border:1px solid #ffcfa8;border-radius:12px;padding:12px 14px;"><b style="font-size:13.5px;color:#b8541a;">📈 今日涨粉动作（30 分钟内做完）</b><div style="font-size:12.5px;line-height:1.8;color:#2c2c2c;margin-top:8px;"><p style="margin:0 0 6px;"><b>1. 发布时段：07:00–09:30 随机落点</b>（今天周一，工作日）。建议 <b>08:30</b> 前后——Day 18 是 08:35、Day 17 是 10:20，错开。</p><p style="margin:0 0 6px;"><b>2. 发完 30 分钟内回到评论区</b>：置顶带核心词那条，再回前 5 条真实评论。</p><p style="margin:0 0 6px;"><b>3. 挂进「品牌在 AI 里的存在感」自检合集</b>：合集名带核心词，覆盖"自检"这个搜索意图。</p><p style="margin:0 0 6px;"><b>4. 自己去搜索框验一次</b>：搜「品牌在 AI 里的存在感」「AI 搜不到我们公司怎么办」，看下拉词里有没有这类内容、你的笔记排在哪——<b>顺便把下拉词抄进 keywords.md</b>，那是真实词源。</p><p style="margin:0 0 6px;"><b>5. 复盘看长尾，不只看当天</b>：这篇别拿 24 小时数据下结论，<b>第 3 天、第 7 天再看一次搜索来源占比</b>——清单型笔记的长尾通常在 3 天后才起来。</p><p style="margin:6px 0 0;font-size:11.5px;color:#8a8a85;"><b>小提醒</b>：「三四个 AI」「外贸朋友」是模糊口径，别写成具体数量或真名；被 AI 说错的例子用化名和改写版本。</p></div></div>'
