          body: '<div style="background:#eef7ff;border:1px solid #9ec9ee;border-radius:12px;padding:12px 14px;"><b style="font-size:13.5px;color:#0a3d62;">🎯 Day 21 · 阶段目标 1000 粉</b><div style="font-size:12.5px;line-height:1.8;color:#2c2c2c;margin-top:8px;"><p style="margin:0 0 6px;"><b>今天的核心任务：作为卖海外 GEO 的人，把价格乱象说透——不是谁黑心，是交付的根本不是同一件事。</b>这是账号第一篇正面聊钱，自带高点击（钱相关），但用吐槽口吻不写成广告。</p><p style="margin:0 0 4px;">· <b>为什么今天写价格</b>：读者最容易被「价格差五六倍」勾住，且行业从没人敢公开拆；拆完反而显专业、显真诚。</p><p style="margin:0 0 4px;">· <b>今天只做 3 件事</b>：① 发第 21 篇；② 评论区问「你问到多少价」；③ 挂进「GEO 避坑」合集。</p><p style="margin:0 0 4px;">· <b>🔍 本轮重点</b>：核心词「GEO 价格」进标题前 20 字、首段、标签前 3 个。</p></div></div>'
